mapper.select:
where vcd.supplier_id in
#{supplierId}
order by vcd.create_time desc

select vcd.id, vcd.supplier_id, vcd.code, vcd.tenant, vcd.deleted, vcd.create_by, vcd.create_time,
vcd.update_by, vcd.update_time
from `meattrade_vip_card` vcd


        vcd.create_time >= #{param.period.begin}


        and vcd.create_time <= #{param.period.end}


        and (vcd.code like concat('%', #{param.keyword}, '%') or
        vcd.supplier_id in

            #{supplierId}

        )

    and vcd.tenant = #{param.tenant}

order by vcd.create_time desc
